import clsx from 'clsx';
import { FormProvider, useForm } from 'react-hook-form';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { getUserRes, setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateWalletAliasMutation } from '~/entities/wallet/api/use-update-wallet-alias-mutation';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { notiBar } from '~/shared/lib/toast';
import { TextInput } from '~/shared/ui/text-input/text-input';

type ManageWalletAliasDialogInputs = {
  walletAliasNm: string;
};

type ManageWalletAliasDialogContentProps = {
  wallet: UserWalletResponse;
};

const WALLET_ALIAS_PATTERN = /^[A-Za-z0-9\uAC00-\uD7A3]+$/;

export const ManageWalletAliasDialogContent = ({ wallet }: ManageWalletAliasDialogContentProps) => {
  const { mutateAsync: updateWalletAlias } = useUpdateWalletAliasMutation();

  const form = useForm<ManageWalletAliasDialogInputs>({
    mode: 'all',
    defaultValues: {
      walletAliasNm: wallet.walletAliasNm ?? '',
    },
  });
  const {
    register,
    handleSubmit,
    formState: { isValid, isSubmitting },
  } = form;

  const handleClose = () => {
    overlay.closeAll();
  };

  const onSubmit = handleSubmit(async ({ walletAliasNm }) => {
    const params = {
      tbCstmrMastr: {
        aliasNm: wallet.aliasNm ?? '',
        walletAliasNm,
      },
    };

    await updateWalletAlias(params.tbCstmrMastr);

    getGlobalQueryClient().setQueryData(queries.cstr.cstmrWalletList.queryKey, (prev: UserWalletResponse[] = []) =>
      prev.map((item) =>
        item.aliasNm === params.tbCstmrMastr.aliasNm
          ? { ...item, walletAliasNm: params.tbCstmrMastr.walletAliasNm }
          : item,
      ),
    );

    if (getUserRes().tbCstmrMastr.aliasNm === params.tbCstmrMastr.aliasNm) {
      setUserRes((prev) => ({
        ...prev,
        tbCstmrMastr: {
          ...prev.tbCstmrMastr,
          walletAliasNm: params.tbCstmrMastr.walletAliasNm,
        },
      }));
    }

    notiBar(i18n.t('text:walletAliasChangeCompleted'));
    handleClose();
  });

  return (
    <FormProvider {...form}>
      <div className="manage-wallet-alias-dialog">
        <div className="sub-top">
          <h2>{i18n.t('manageMyWalletName')}</h2>
          <button type="button" onClick={handleClose} className="btn close-btn">
            <span>{i18n.t('close')}</span>
          </button>
        </div>
        <form onSubmit={onSubmit} className="has-btm-btn manage-wallet-alias-dialog__form">
          <div className="content sub manage-wallet-alias-dialog__content">
            <div className="manage-wallet-alias-dialog__section-title">{i18n.t('walletInfo')}</div>
            <dl className="manage-wallet-alias-dialog__info-list">
              <div className="manage-wallet-alias-dialog__info-row">
                <dt className="manage-wallet-alias-dialog__info-label">{i18n.t('walletAliasNm')}</dt>
                <dd>{wallet.aliasNm ?? ''}</dd>
              </div>
              <div className="manage-wallet-alias-dialog__info-row">
                <dt className="manage-wallet-alias-dialog__info-label">{i18n.t('linkedAccount')}</dt>
                <dd>{wallet.realAcnutNo ?? ''}</dd>
              </div>
            </dl>

            <div className="manage-wallet-alias-dialog__input-section">
              <TextInput
                label={i18n.t('inputWalletName')}
                placeholder={i18n.t('defaultWallet')}
                description={i18n.t('validation:textAndNumbersAllowed')}
                maxLength={20}
                isErrorPaddingPresent={false}
                {...register('walletAliasNm', {
                  required: i18n.t('validation:enterAliasName'),
                  pattern: {
                    value: WALLET_ALIAS_PATTERN,
                    message: i18n.t('validation:textAndNumbersAllowed'),
                  },
                })}
              />
            </div>
          </div>
          <div className="btm-btn-area">
            <button
              type="submit"
              className={clsx('btm-btn app', {
                disabled: !isValid || isSubmitting,
              })}
              disabled={!isValid || isSubmitting}
            >
              {i18n.t('save')}
            </button>
          </div>
        </form>
      </div>
    </FormProvider>
  );
};
