import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updatePrimaryWallet = (aliasNm: string) => {
  return resultify(axios.post<any>(API_URLS.updateCstmrPrimaryWallet(aliasNm), {}));
};

export const useUpdatePrimaryWalletMutation = (options?: MutationOptions<string, CBDCAxiosError, string>) => {
  const mutation = useMutation<string, CBDCAxiosError, string>({
    ...options,
    mutationFn: (params: string) => updatePrimaryWallet(params),
  });

  return {
    ...mutation,
  };
};
