import clsx from 'clsx';
import { memo, useMemo } from 'react';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { sortWalletsForDisplay } from '~/entities/wallet/lib/sort-wallets-for-display';
import { FunctionButtons } from '~/entities/wallet/ui/token-list/function-buttons';
import i18n from '~/shared/i18n/i18n';

type ManageMyWalletListProps = {
  wallets: UserWalletResponse[];
  shortBankName: string;
  isHideBalance: boolean;
  latestCoinItem: TokenItem;
  openQRScanner: (options: { scannerType: ScannerType }) => void;
  onSetPrimary: (aliasNm: string) => void | Promise<void>;
  // onOpenMoreMenu: (aliasNm: string, walletId: string) => void;
  onOpenMoreMenu: (wallet: UserWalletResponse) => void;
  onCopyAddress: (aliasNm: string) => void;
  onDepositToken: (wallet: UserWalletResponse) => void | Promise<void>;
};

export const ManageMyWalletList = memo(function ManageMyWalletList({
  wallets,
  shortBankName,
  isHideBalance,
  latestCoinItem,
  openQRScanner,
  onSetPrimary,
  onOpenMoreMenu,
  onCopyAddress,
  onDepositToken,
}: ManageMyWalletListProps) {
  const sortedWallets = useMemo(() => sortWalletsForDisplay(wallets, { priority: 'primary' }), [wallets]);

  if (wallets.length === 0) {
    return null;
  }

  return (
    <>
      {sortedWallets.map((wallet) => {
        const aliasNm = wallet.aliasNm?.trim() ?? '';
        const walletId = wallet.walletId ?? '';
        const isWalletBlocked = !aliasNm || wallet.isWalletBlocked;
        const isPrimaryWallet = wallet.priAliasNm === wallet.aliasNm;

        return (
          <div
            className={clsx('my-wallet-info-wrapper', { disabled: isWalletBlocked })}
            key={wallet.aliasNm ?? wallet.walletId ?? wallet.realAcnutNo}
          >
            <div className="my-wallet-info-area">
              <div className="my-wallet-asset-info">
                <div className="wallet-asset-info-sttus">
                  <span style={{ fontSize: '18px', padding: '0px 5px 0px 0px' }}>
                    {wallet.walletAliasNm || '전자지갑'}
                  </span>
                  {isPrimaryWallet ? (
                    <span className="company">대표지갑</span>
                  ) : (
                    !isWalletBlocked && (
                      <span className="etc" onClick={isWalletBlocked ? undefined : () => onSetPrimary(aliasNm)}>
                        대표지갑으로 설정
                      </span>
                    )
                  )}
                  {isWalletBlocked && <span className="spd">{i18n.t('transactionRestriction')}</span>}
                </div>
                <button
                  type="button"
                  className="btn top-more-btn"
                  onClick={() => onOpenMoreMenu(wallet)}
                  disabled={isWalletBlocked}
                  data-testid="more-button"
                >
                  <span>더보기 버튼</span>
                </button>
              </div>
              <div style={{ margin: '10px 0px' }}>
                <div className="wallet-asset-info">
                  <button
                    type="button"
                    className={`my-wallet-account dark ${wallet.bankCd}`}
                    onClick={() => onCopyAddress(aliasNm)}
                    disabled={isWalletBlocked}
                  >
                    {shortBankName} {wallet.aliasNm}
                  </button>
                </div>
                <div className="wallet-asset-info">
                  <span style={{ marginRight: '10px' }}>연결 계좌</span> <span>{wallet.realAcnutNo}</span>
                </div>
                <div className="wallet-info">
                  <button
                    type="button"
                    className="blce-btn"
                    onClick={() => onDepositToken(wallet)}
                    disabled={isWalletBlocked}
                  >
                    {i18n.t('depositToken')}
                    {isHideBalance ? (
                      <>{i18n.t('showBalance')}</>
                    ) : (
                      <b>
                        {(wallet.acnutnoBlce || 0).toLocaleString()} {i18n.t('won')}
                      </b>
                    )}
                  </button>
                </div>
              </div>
              {wallet.tokenList && wallet.tokenList.length > 0 && (
                <FunctionButtons
                  item={wallet.tokenList[0]}
                  openQRScanner={openQRScanner}
                  disabled={wallet.isWalletBlocked}
                  aliasNmForUpdateDefault={wallet.aliasNm!}
                />
              )}
            </div>
          </div>
        );
      })}
    </>
  );
});
