import { isEmpty } from 'lodash-es';
import { Fragment, useCallback, useMemo, useState } from 'react';
import { useStore } from '~/app/store/store';
import { useSetHeaderTitle, useSetIsPullToRefreshEnabled } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import {
  ManageMyWalletMoreBottomSheet,
  ManageMyWalletMoreMenuType,
} from '~/entities/menu/ui/manage-my-wallet-more-bottom-sheet';
import { ManageWalletAliasDialogContent } from '~/entities/menu/ui/manage-wallet-alias-dialog-content';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { useQRScan } from '~/entities/qr-scan/lib/use-qr-scan';
import { findTokenItemByType } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { useRefreshUserInfo } from '~/entities/user/lib/use-refresh-user-info';
import { useDeleteWalletMutation } from '~/entities/wallet/api/use-delete-wallet-mutation';
import { useUpdateDefaultWalletMutation } from '~/entities/wallet/api/use-update-default-wallet-mutation';
import { useUpdatePrimaryWalletMutation } from '~/entities/wallet/api/use-update-primary-wallet-mutation';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { LinkToHistoryList } from '~/entities/wallet/ui/manage-my-wallet/link-to-history-list';
import { ManageMyWalletList } from '~/entities/wallet/ui/manage-my-wallet/manage-my-wallet-list';
import { StepBeforeRegister, TokenItemType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { useCopy, useNavigate } from '~/shared/lib/hooks';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const ManageMyWalletPage = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const hasBusinessAccount = Boolean(userRes?.tbCstmrMastr?.ewaBizNo);
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');
  const { data: walletListRes } = useGetCstmrWalletListQuery();
  const { copyText } = useCopy();
  const { openQRScanner } = useQRScan();
  const { openPinBottomSheet } = usePinBottomSheet();
  const { mutateAsync: updatePrimaryWallet } = useUpdatePrimaryWalletMutation();
  const { mutateAsync: updateDefaultWallet } = useUpdateDefaultWalletMutation();
  const { mutateAsync: deleteWallet } = useDeleteWalletMutation();
  const { navigate, reload } = useNavigate();

  const latestCoinItem = findTokenItemByType(userRes?.tbCstmrMastr?.tokenList, TokenItemType.DC1);

  const [isTermsOpen, setIsTermsOpen] = useState<boolean>(false);
  const [selectedAliasNm, setSelectedAliasNm] = useState<string>('');
  const [selectedWalletId, setSelectedWalletId] = useState<string>('');
  const [selectedWallet, setSelectedWallet] = useState<UserWalletResponse>({} as UserWalletResponse);

  useRefreshUserInfo();
  //useManageMyWalletHeaderRight(); //n개지갑 반영시 추가
  useSetHeaderTitle(i18n.t('manageMyWallet'));
  useSetIsPullToRefreshEnabled(true);

  const isHideBalance = useStore((state) => state.appConfigSlice.isHideBalance);
  const tokenList = useMemo(() => walletListRes || [], [walletListRes]);

  const updateCstmrPriWallet = useCallback(
    async (aliasNm: string) => {
      if (isEmpty(aliasNm)) {
        return;
      }

      await updatePrimaryWallet(aliasNm);
    },
    [updatePrimaryWallet],
  );

  const handleSetPri = useCallback(
    async (aliasNm: string) => {
      await updateCstmrPriWallet(aliasNm);
      reload();
    },
    [reload, updateCstmrPriWallet],
  );

  const updateCstmrDfltWallet = useCallback(
    async (aliasNm: string) => {
      if (isEmpty(aliasNm)) {
        return;
      }

      await updateDefaultWallet(aliasNm);
    },
    [updateDefaultWallet],
  );

  const handleOpenMoreMenu = useCallback((wallet: UserWalletResponse) => {
    const { aliasNm, walletId } = wallet;
    if (isEmpty(aliasNm)) {
      return;
    }

    setSelectedAliasNm(aliasNm!);
    setSelectedWalletId(walletId!);
    setSelectedWallet(wallet);
    setIsTermsOpen(true);
  }, []);

  const handleCloseMoreMenu = useCallback(() => {
    setIsTermsOpen(false);
  }, []);

  const handleOpenWalletAliasDialog = useCallback((wallet: UserWalletResponse) => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          fullScreenMode
          message={<ManageWalletAliasDialogContent wallet={wallet} />}
        />
      );
    });
  }, []);

  const deleteMyWallet = useCallback(async () => {
    if (!userRes?.tbCstmrMastr?.cstmrNo) {
      console.error('cstmrNo is null');
      return;
    }

    openPinBottomSheet((close) => {
      close();
      setTimeout(async () => {
        await deleteWallet({
          tbCstmrMastr: {
            walletId: selectedWalletId,
            //cstmrNo: userRes?.tbCstmrMastr?.cstmrNo || '',
          },
        });
      }, 0);
    });
  }, [deleteWallet, openPinBottomSheet, selectedWalletId, userRes?.tbCstmrMastr?.cstmrNo]);

  const handleNavigateToBusinessAccount = useCallback(
    (aliasNm: string) => {
      window.setTimeout(() => {
        navigate(PATHS.myWallet.business, {
          state: { step: StepBeforeRegister['재설정'], aliasNm },
        });
      }, 0);
    },
    [navigate],
  );

  const handleChangeToBusinessAccount = useCallback(
    (aliasNm: string) => {
      !hasBusinessAccount
        ? overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
            return (
              <Dialog
                afterLeave={unmount}
                open={isOpen}
                onClose={close}
                message={i18n.t('validation:changeToBusinessAccountConfirmation')}
                buttonLabel={[i18n.t('cancel'), i18n.t('confirm')]}
                onConfirmClick={() => {
                  closeDialog(() => {
                    navigate(PATHS.myWallet.business, {
                      state: { step: StepBeforeRegister['등록'], aliasNm: aliasNm },
                    });
                  });
                }}
              />
            );
          })
        : handleNavigateToBusinessAccount(aliasNm);
    },
    [handleNavigateToBusinessAccount, hasBusinessAccount, navigate],
  );

  const handleDeleteMyWallet = useCallback(() => {
    if (selectedWallet.acnutnoBlce == null) {
      console.error('acnutnoBlce is null');
      return;
    }

    if (selectedWallet.acnutnoBlce > 0) {
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
        return (
          <Dialog
            afterLeave={unmount}
            open={isOpen}
            onClose={close}
            message={
              <Fragment>
                예금 토큰 잔액이 0원인 경우에만
                <br />
                지갑을 삭제할 수 있습니다.
              </Fragment>
            }
          />
        );
      });
      return;
    }

    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={i18n.t('validation:walletDeletionConfirmation')}
          buttonLabel={[i18n.t('cancel'), i18n.t('confirm')]}
          onConfirmClick={deleteMyWallet}
        />
      );
    });
  }, [deleteMyWallet, selectedWallet]);

  const handleOpenManageWalletAlias = useCallback(
    (aliasNm: string) => {
      const selectWallet = tokenList.find((item) => item.aliasNm === aliasNm);
      if (!selectWallet) {
        return;
      }

      setTimeout(() => {
        handleOpenWalletAliasDialog(selectWallet);
      }, 0);
    },
    [handleOpenWalletAliasDialog, tokenList],
  );

  const handleNavigateToAutoOnOffRamp = useCallback(
    (aliasNm: string) => {
      window.setTimeout(() => {
        navigate(PATHS.setAutoOnOffRamp.root, { state: { aliasNm: aliasNm } });
      }, 0);
    },
    [navigate],
  );

  const moreMenuActionMap = useMemo<Partial<Record<ManageMyWalletMoreMenuType, (aliasNm: string) => void>>>(
    () => ({
      manageWalletAlias: handleOpenManageWalletAlias,
      autoOnOffRampSetting: handleNavigateToAutoOnOffRamp,
      changeToBusinessAccount: (aliasNm: string) => {
        handleChangeToBusinessAccount(aliasNm);
      },
      deleteWallet: () => {
        handleDeleteMyWallet();
      },
    }),
    [handleChangeToBusinessAccount, handleDeleteMyWallet, handleNavigateToAutoOnOffRamp, handleOpenManageWalletAlias],
  );

  const handleSelectMoreMenu = useCallback(
    (menuType: ManageMyWalletMoreMenuType, aliasNm: string) => {
      setIsTermsOpen(false);
      moreMenuActionMap[menuType]?.(aliasNm);
    },
    [moreMenuActionMap],
  );

  const handleCopyWalletAddress = useCallback(
    (aliasNm: string) => {
      copyText({ value: aliasNm, label: i18n.t('text:walletAddressCopied') });
    },
    [copyText],
  );

  const handleDepositToken = useCallback(
    async (wallet: UserWalletResponse) => {
      await updateCstmrDfltWallet(wallet.aliasNm ?? '');
      navigate(
        `${PATHS.myWallet.history}?coinType=${TokenItemType.DC1}&walletInsttCd=${wallet.bankCd}&coinId=${'0'}&aliasNm=${wallet.aliasNm}&viewType=${WalletHistoryViewType.TOKEN_HISTORY}`,
      );
    },
    [navigate, updateCstmrDfltWallet],
  );

  return (
    <div className="content sub">
      {/* 260415 검색input 삭제 */}
      {/* <SearchInput /> */}
      <div style={{ margin: '10px', alignSelf: 'center' }}>
        <LinkToHistoryList />
      </div>
      <ManageMyWalletList
        wallets={tokenList}
        shortBankName={shortBankName!}
        isHideBalance={isHideBalance}
        latestCoinItem={latestCoinItem}
        openQRScanner={openQRScanner}
        onSetPrimary={handleSetPri}
        onOpenMoreMenu={handleOpenMoreMenu}
        onCopyAddress={handleCopyWalletAddress}
        onDepositToken={handleDepositToken}
      />
      <ManageMyWalletMoreBottomSheet
        isSheetOpen={isTermsOpen}
        aliasNm={selectedAliasNm}
        wallet={selectedWallet}
        hasBusinessAccount={hasBusinessAccount}
        onClose={handleCloseMoreMenu}
        onSelectMenu={handleSelectMoreMenu}
      />
    </div>
  );
};
