import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CstmrUpdateParams } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updateWalletAlias = (tbCstmrMastr: Pick<CstmrUpdateParams, 'aliasNm' | 'walletAliasNm'>) => {
  return resultify(axios.post<unknown>(API_URLS.updateWalletAlias, { tbCstmrMastr }));
};

export const useUpdateWalletAliasMutation = (
  options?: MutationOptions<Pick<CstmrUpdateParams, 'aliasNm' | 'walletAliasNm'>, CBDCAxiosError, unknown>,
) => {
  const mutation = useMutation<unknown, CBDCAxiosError, Pick<CstmrUpdateParams, 'aliasNm' | 'walletAliasNm'>>({
    ...options,
    mutationFn: (tbCstmrMastr) => updateWalletAlias(tbCstmrMastr),
  });

  return {
    ...mutation,
  };
};
